'use strict';
const assert = require('node:assert/strict'), fs = require('node:fs');
const assetPath = require('node:path').resolve(process.env.LTS_OVERDUE_ASSET || 'releases/v280/lts-v275-overdue-visibility.js');
const api = require(assetPath);
const checks = [];
const check = (name, condition) => { assert(condition, name); checks.push(name); };
const event = {source:'current_event', source_ref:'fixture-iptu', event_date:'2026-09-19', account:'Itaú', description:'IPTU <teste>', signed_amount:'-150.25'};
const flow = rows => ({from:'2026-09-20',to:'2026-09-20',current_future:{current_anchor_date:'2026-09-20'},observed_bank_movements:{pending_projections:rows}});
const context = {today:'2026-09-20',account:'Consolidado',range:{from:'2026-09-20',to:'2026-09-20'}};
const run = (rows, extra) => api.model(flow(rows), {...context,...extra});
const text = view => api.markup(view,false);
check('BRT day before midnight',api.businessDay(new Date('2026-09-20T02:59:59Z'))==='2026-09-19');
check('BRT day after midnight',api.businessDay(new Date('2026-09-20T03:00:00Z'))==='2026-09-20');
check('UTC midnight does not advance BRT',api.businessDay(new Date('2026-09-20T00:00:00Z'))==='2026-09-19');
check('Invalid calendar dates rejected',api.day('2026-02-30')===null&&api.day('2026-13-01')===null);
const original=JSON.stringify(event),v=run([event]);
check('Overdue retained under today-only range',v.status==='ready'&&v.rows.length===1&&v.rows[0].dueDate==='2026-09-19');
check('Original fields unchanged',JSON.stringify(event)===original&&v.rows[0].amount===-150.25);
check('Payment remains unconfirmed',text(v).includes('baixa ainda não vinculada no LTS'));
check('Original due date rendered',text(v).includes('Vencimento 19/09/2026'));
check('Signed amount rendered',text(v).includes('-R$')&&text(v).includes('150,25'));
check('Descriptions escaped',text(v).includes('&lt;teste&gt;')&&!text(v).includes('<teste>'));
check('Unknown source differs from known empty',api.model({...flow([]),observed_bank_movements:{}},context).status==='source_missing'&&run([]).status==='ready');
check('Empty is explicitly qualified',text(run([])).includes('nesta lista recebida'));
check('Null collection is not empty',api.model({...flow([]),observed_bank_movements:{pending_projections:null}},context).status==='invalid_source');
check('Error cannot display old amount',!text(api.model({...flow([event]),error:'failed'},context)).includes('150,25'));
check('Loading cannot display old amount',run([event],{loading:true}).status==='loading'&&!text(run([event],{loading:true})).includes('150,25'));
check('Range mismatch guarded',api.model({...flow([event]),from:'2026-09-19'},context).status==='range_mismatch');
check('Stale generation is not zero',api.model({...flow([]),current_future:{current_anchor_date:'2026-09-19'}},context).status==='stale');
check('Missing calculation date is unverified',api.model({...flow([]),current_future:{}},context).status==='undated');
check('Contradictory anchors guarded',api.model({...flow([event]),projected_operational_anchor:{as_of:'2026-09-19'}},context).status==='stale');
check('Documented current anchor fallback',api.model({...flow([event]),current_future:{},projected_operational_anchor:{as_of:'2026-09-20'}},context).rows.length===1);
check('Today and future forecasts excluded from overdue',run([{...event,event_date:'2026-09-20'},{...event,event_date:'2026-09-21'}]).rows.length===0);
check('Bank selection is isolated',run([event],{account:'C6'}).rows.length===0&&run([event],{account:'Itaú'}).rows.length===1);
check('Bank-confirmed row not reintroduced',run([{...event,bank_confirmed:true}]).rows.length===0);
check('Suppressed reimbursement not reintroduced',run([{...event,source_ref:'reimbursement',signed_amount:275.50,is_suppressed:true}]).rows.length===0);
check('Income confirmation uses correct wording',text(run([{...event,signed_amount:120}])).includes('crédito ainda não vinculado no LTS'));
check('Same canonical source/date deduplicates',run([event,{...event}]).rows.length===1);
check('Conflicting duplicate does not invent one amount',run([event,{...event,signed_amount:-2000}]).status==='partial'&&run([event,{...event,signed_amount:-2000}]).rows.length===0);
check('Cross-bank identity conflict remains partial in each bank', ['Consolidado','Itaú','Bradesco'].every(account => {const view=run([event,{...event,account:'Bradesco'}],{account});return view.status==='partial'&&view.rows.length===0}));
check('Contradictory confirmed copy cannot resurrect pending',run([event,{...event,bank_confirmed:true}]).status==='partial'&&run([event,{...event,bank_confirmed:true}]).rows.length===0);
check('Contradictory suppressed copy cannot resurrect pending',run([event,{...event,is_suppressed:true}]).status==='partial'&&run([event,{...event,is_suppressed:true}]).rows.length===0);
check('Distinct obligations with equal value stay distinct',run([event,{...event,source_ref:'second'}]).rows.length===2);
check('Split dates remain distinct',run([event,{...event,event_date:'2026-09-18'}]).rows.length===2);
check('Malformed row does not certify empty',run([{...event,signed_amount:null}]).status==='partial'&&!text(run([{...event,signed_amount:null}])).includes('Nenhuma'));
check('Missing identity is incomplete',run([{event_date:'2026-09-19',account:'Itaú',signed_amount:-10}]).status==='partial');
check('Nonfinite and booleans not numeric money',run([{...event,signed_amount:Infinity},{...event,signed_amount:true}]).status==='partial');
check('Old obligation is not aged away',run([{...event,event_date:'2020-01-01'}]).rows.length===1);
check('Expanded state controlled by presentation',api.markup(v,true).includes('<details open>'));
check('No totals or alternative balance produced',!('total' in v)&&!('balance' in v)&&!('payment_date' in v)&&!text(v).includes('Saldo após'));
check('No RPC/writer/browser API in implementation',!/(?:S\.rpc|fetch\(|XMLHttpRequest|localStorage|sessionStorage|MutationObserver|setInterval)/.test(fs.readFileSync(assetPath,'utf8')));
const result={status:'PASS',count:checks.length,checks,limits:'Pure presentation model and HTML checks. No product SQL or browser.'};
fs.writeFileSync('qa/v280-overdue-contract-results.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result,null,2));
